package com.livesub.app;
import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.provider.Settings;import android.speech.*;import android.view.*;import android.widget.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import org.json.*;
public class MainActivity extends Activity{
 int REQ=40; EditText key; Spinner src,dst; TextView status,heard,translated; SpeechRecognizer sr; boolean active=false; Handler h=new Handler(Looper.getMainLooper()); ExecutorService net=Executors.newSingleThreadExecutor();
 public void onCreate(Bundle b){super.onCreate(b);ui();}
 void ui(){ScrollView sc=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);l.setBackgroundColor(0xff0b1024);sc.addView(l);setContentView(sc);
 TextView title=t("LiveSub",30);title.setGravity(17);l.addView(title);TextView sub=t("ترجمة مباشرة إلى العربية",16);sub.setGravity(17);l.addView(sub);
 status=t("جاهز — اختر اللغة ثم ابدأ",14);l.addView(status);key=new EditText(this);key.setSingleLine(true);key.setHint("مفتاح Gemini API");key.setInputType(129);l.addView(key);
 l.addView(t("لغة الكلام",15));src=sp(new String[]{"English (US)","French","Spanish","German","Turkish","Arabic"});l.addView(src);
 l.addView(t("لغة الترجمة",15));dst=sp(new String[]{"Arabic","English","French","Spanish","German","Turkish"});l.addView(dst);
 Button start=btn("▶ بدء الترجمة");start.setOnClickListener(v->start());l.addView(start);Button stop=btn("■ إيقاف");stop.setOnClickListener(v->stop());l.addView(stop);
 Button ov=btn("إظهار الترجمة فوق التطبيقات");ov.setOnClickListener(v->overlay());l.addView(ov);
 l.addView(t("الكلام المسموع",17));heard=panel();l.addView(heard);l.addView(t("الترجمة",17));translated=panel();l.addView(translated);
 TextView note=t("ملاحظة: هذه النسخة تلتقط الصوت من الميكروفون. الصوت الداخلي للتطبيقات غير مفعّل بعد.",13);note.setTextColor(0xffffcc80);l.addView(note);
 }
 TextView t(String s,int z){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(-1);x.setPadding(0,12,0,12);return x;} TextView panel(){TextView x=t("ستظهر النتيجة هنا",17);x.setBackgroundColor(0xff26334f);return x;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;} Spinner sp(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;}
 String locale(){String s=(String)src.getSelectedItem();if(s.startsWith("French"))return "fr-FR";if(s.startsWith("Spanish"))return "es-ES";if(s.startsWith("German"))return "de-DE";if(s.startsWith("Turkish"))return "tr-TR";if(s.startsWith("Arabic"))return "ar";return "en-US";}
 void start(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ);return;}if(!SpeechRecognizer.isRecognitionAvailable(this)){status.setText("خدمة التعرف الصوتي غير متاحة على الجهاز");return;}stop();active=true;sr=SpeechRecognizer.createSpeechRecognizer(this);Intent in=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);in.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);in.putExtra(RecognizerIntent.EXTRA_LANGUAGE,locale());in.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);in.putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE,false);
 sr.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){status.setText("أستمع الآن…");}public void onBeginningOfSpeech(){}public void onRmsChanged(float f){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){status.setText("أعالج الكلام…");}public void onError(int e){if(active&&e!=SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS)h.postDelayed(()->listen(in),800);else status.setText("توقف الاستماع؛ تحقق من إذن الميكروفون");}public void onResults(Bundle b){ArrayList<String>a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a!=null&&!a.isEmpty()){heard.setText(a.get(0));translate(a.get(0));}if(active)h.postDelayed(()->listen(in),500);}public void onPartialResults(Bundle b){ArrayList<String>a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a!=null&&!a.isEmpty())heard.setText(a.get(0));}public void onEvent(int e,Bundle b){}});
 listen(in);
 }
 void listen(Intent i){if(!active||sr==null)return;try{sr.startListening(i);}catch(Exception e){status.setText("تعذر استئناف الاستماع؛ اضغط بدء من جديد");}}
 void stop(){active=false;h.removeCallbacksAndMessages(null);if(sr!=null){try{sr.cancel();sr.destroy();}catch(Exception e){}sr=null;}status.setText("تم إيقاف الاستماع");}
 void translate(String text){String api=key.getText().toString().trim();if(api.isEmpty()){translated.setText("أدخل مفتاح Gemini API لتفعيل الترجمة.");return;}status.setText("جارٍ ترجمة الكلام…");net.execute(()->{try{String prompt="Translate this spoken text into "+dst.getSelectedItem()+". Return only the translation. Text: "+text;JSONObject body=new JSONObject().put("contents",new JSONArray().put(new JSONObject().put("parts",new JSONArray().put(new JSONObject().put("text",prompt)))));URL u=new URL("https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key="+URLEncoder.encode(api,"UTF-8"));HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();InputStream stream=code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();stream.transferTo(out);c.disconnect();if(code>=300)throw new Exception("HTTP "+code);JSONObject j=new JSONObject(out.toString("UTF-8"));String result=j.getJSONArray("candidates").getJSONObject(0).getJSONObject("content").getJSONArray("parts").getJSONObject(0).getString("text").trim();runOnUiThread(()->{translated.setText(result);status.setText("اكتملت الترجمة");});}catch(Exception e){runOnUiThread(()->status.setText("فشلت الترجمة: "+e.getMessage()));}});}
 void overlay(){if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION));return;}Intent i=new Intent(this,SubtitleOverlayService.class);i.putExtra("subtitle",translated.getText().toString());startService(i);}
 public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==REQ&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)start();}
 protected void onDestroy(){stop();net.shutdownNow();super.onDestroy();}
}